// Extract event type and data from Stripe Trigger
const event = $input.first().json;

return [{
  json: {
    eventType: event.type,
    eventId: event.id,
    created: new Date(event.created * 1000).toISOString(),
    data: event.data.object,
    livemode: event.livemode,
    customerId: event.data.object.customer || null,
    chargeId: event.data.object.id || null
  }
}];

// Process charge.succeeded event with enriched data from Stripe API
const customer = $input.first().json;
const charge = $('Stripe - Get Charge').first().json;

// Extract payment details from expanded charge
const amount = charge.amount / 100;
const currency = charge.currency.toUpperCase();
const chargeId = charge.id;
const customerId = charge.customer?.id || charge.customer;
const description = charge.description || 'Payment';
const receiptUrl = charge.receipt_url || '';

// Get ACCURATE fee from expanded balance_transaction
let feeAmount = 0;
let netAmount = amount;
if (charge.balance_transaction && typeof charge.balance_transaction === 'object') {
  feeAmount = charge.balance_transaction.fee / 100;
  netAmount = charge.balance_transaction.net / 100;
}

// Enriched customer data
const customerName = customer.name || charge.billing_details?.name || customer.email || 'Unknown Customer';
const customerEmail = customer.email || charge.billing_details?.email || '';
const customerPhone = customer.phone || '';
const customerAddress = customer.address ? 
  [customer.address.line1, customer.address.city, customer.address.state, customer.address.postal_code, customer.address.country].filter(Boolean).join(', ') : '';
const customerCreated = customer.created ? new Date(customer.created * 1000).toISOString().split('T')[0] : '';

// Transaction date
const transactionDate = new Date(charge.created * 1000).toISOString().split('T')[0];

// Payment method info
const cardBrand = charge.payment_method_details?.card?.brand || '';
const cardLast4 = charge.payment_method_details?.card?.last4 || '';
const cardFunding = charge.payment_method_details?.card?.funding || '';
const cardInfo = cardBrand && cardLast4 ? `${cardBrand.toUpperCase()} ****${cardLast4}` : '';

const isNewCustomer = customerCreated === transactionDate;

return [{
  json: {
    // For Google Sheets Incomes tab
    date: transactionDate,
    description: `${customerName} - ${description}`,
    customerName,
    customerEmail,
    amount,
    stripeFee: feeAmount,
    netAmount,
    type: 'Customer Payment',
    transactionId: chargeId,
    status: 'Cleared',
    paymentMethod: cardInfo + (cardFunding ? ` (${cardFunding})` : ''),
    notes: `${customerAddress ? 'Address: ' + customerAddress + ' | ' : ''}${isNewCustomer ? 'NEW CUSTOMER' : 'Customer since: ' + customerCreated}`,
    createdAt: new Date().toISOString(),
    // For Slack notification
    isNewCustomer,
    customerPhone,
    currency
  }
}];

