// Process invoice.paid event
const data = $input.first().json.data;

// Determine if this is OUR expense or customer REVENUE
const customerEmail = data.customer_email || '';
const isOurExpense = customerEmail.includes('aasani.ai') || 
                     customerEmail.includes('ayub@') ||
                     customerEmail === 'ayub@aasani.ai';

// Extract invoice details
const invoiceId = data.id;
const amount = data.amount_paid / 100;
const currency = data.currency.toUpperCase();
const customerId = data.customer;
const customerName = data.customer_name || data.customer_email || 'Unknown';
const invoiceUrl = data.hosted_invoice_url || data.invoice_pdf || '';
const transactionDate = new Date(data.effective_at * 1000 || data.created * 1000).toISOString().split('T')[0];

// Get line item descriptions
let description = 'Subscription Payment';
if (data.lines && data.lines.data && data.lines.data.length > 0) {
  description = data.lines.data.map(line => line.description || line.plan?.nickname || 'Subscription').join(', ');
}

// Subscription info
const periodStart = data.period_start ? new Date(data.period_start * 1000).toISOString().split('T')[0] : '';
const periodEnd = data.period_end ? new Date(data.period_end * 1000).toISOString().split('T')[0] : '';

return [{
  json: {
    isOurExpense,
    // For Google Sheets
    date: transactionDate,
    description: isOurExpense ? `${description} Subscription` : `${customerName} - ${description}`,
    customerName,
    customerEmail,
    amount,
    transactionId: invoiceId,
    invoiceUrl,
    periodStart,
    periodEnd,
    createdAt: new Date().toISOString()
  }
}];

// Process payment failed event
const data = $input.first().json.data;

const invoiceId = data.id;
const amount = (data.amount_due || data.total) / 100;
const customerName = data.customer_name || data.customer_email || 'Unknown';
const customerEmail = data.customer_email || '';
const transactionDate = new Date(data.created * 1000).toISOString().split('T')[0];

// Failure details
const failureMessage = data.last_finalization_error?.message || 
                       data.charge?.failure_message || 
                       'Payment failed';
const attemptCount = data.attempt_count || 1;
const nextAttempt = data.next_payment_attempt 
  ? new Date(data.next_payment_attempt * 1000).toISOString()
  : null;
const hostedInvoiceUrl = data.hosted_invoice_url || '';

return [{
  json: {
    // For Google Sheets
    date: transactionDate,
    description: `FAILED: ${customerName} - $${amount.toFixed(2)}`,
    customerName,
    customerEmail,
    amount,
    transactionId: invoiceId,
    status: 'Failed',
    notes: `Reason: ${failureMessage} | Attempt #${attemptCount}`,
    createdAt: new Date().toISOString(),
    // For Slack
    failureMessage,
    attemptCount,
    nextAttempt,
    hostedInvoiceUrl
  }
}];

