// Process subscription created/deleted
const data = $input.first().json.data;
const eventType = $input.first().json.eventType;
const isCreated = eventType === 'customer.subscription.created';

const subscriptionId = data.id;
const customerId = data.customer;
const status = data.status;
const canceledAt = data.canceled_at ? new Date(data.canceled_at * 1000).toISOString() : null;

// Get plan details
let planName = 'Unknown Plan';
let amount = 0;
let interval = 'month';

if (data.items && data.items.data && data.items.data.length > 0) {
  const item = data.items.data[0];
  planName = item.price?.nickname || item.plan?.nickname || 'Subscription';
  amount = (item.price?.unit_amount || item.plan?.amount || 0) / 100;
  interval = item.price?.recurring?.interval || item.plan?.interval || 'month';
}

const periodStart = new Date(data.current_period_start * 1000).toISOString().split('T')[0];
const periodEnd = new Date(data.current_period_end * 1000).toISOString().split('T')[0];

return [{
  json: {
    action: isCreated ? 'Created' : 'Canceled',
    subscriptionId,
    customerId,
    status,
    planName,
    amount,
    interval,
    periodStart,
    periodEnd,
    canceledAt
  }
}];

// Process refund event
const data = $input.first().json.data;

const chargeId = data.id;
const refundId = data.refunds?.data?.[0]?.id || `refund_${chargeId}`;
const originalAmount = data.amount / 100;
const refundedAmount = data.amount_refunded / 100;
const customerName = data.billing_details?.name || 'Unknown';
const customerEmail = data.billing_details?.email || data.customer_email || '';
const transactionDate = new Date().toISOString().split('T')[0];
const reason = data.refunds?.data?.[0]?.reason || 'Customer request';

return [{
  json: {
    // For Google Sheets
    date: transactionDate,
    description: `REFUND: ${customerName} - $${refundedAmount.toFixed(2)}`,
    customerName,
    customerEmail,
    amount: -refundedAmount,
    transactionId: refundId,
    notes: `Original charge: ${chargeId} | Reason: ${reason}`,
    createdAt: new Date().toISOString(),
    // For Slack
    originalAmount,
    refundedAmount,
    reason
  }
}];

